ALTER TABLE veloryz_studio.studio_payments ADD COLUMN receipt_reference text NOT NULL DEFAULT '', ADD COLUMN reconciliation_note text NOT NULL DEFAULT '', ADD COLUMN verified_at text NOT NULL DEFAULT '';
CREATE TABLE veloryz_studio.studio_payment_events(payment_id text NOT NULL REFERENCES veloryz_studio.studio_payments(id) ON DELETE RESTRICT,version integer NOT NULL,previous_status text NOT NULL,status text NOT NULL,receipt_reference text NOT NULL,reconciliation_note text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(payment_id,version));
ALTER TABLE veloryz_studio.studio_payment_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON veloryz_studio.studio_payment_events FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT ON veloryz_studio.studio_payment_events TO service_role;
CREATE FUNCTION veloryz_studio.r51_payment_audit() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $fn$ BEGIN
 IF NEW.version<>OLD.version THEN INSERT INTO veloryz_studio.studio_payment_events(payment_id,version,previous_status,status,receipt_reference,reconciliation_note) VALUES(NEW.id,NEW.version,OLD.status,NEW.status,NEW.receipt_reference,NEW.reconciliation_note); END IF;
 RETURN NEW;
END; $fn$;
REVOKE ALL ON FUNCTION veloryz_studio.r51_payment_audit() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veloryz_studio.r51_payment_audit() TO service_role;
CREATE TRIGGER r51_payment_audit AFTER UPDATE ON veloryz_studio.studio_payments FOR EACH ROW EXECUTE FUNCTION veloryz_studio.r51_payment_audit();
CREATE TABLE veloryz_studio.studio_finance_budgets(reference text PRIMARY KEY,agreed_paise bigint NOT NULL CHECK(agreed_paise BETWEEN 100 AND 1000000000),version integer NOT NULL CHECK(version>0),updated_at text NOT NULL);
ALTER TABLE veloryz_studio.studio_finance_budgets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON veloryz_studio.studio_finance_budgets FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON veloryz_studio.studio_finance_budgets TO service_role;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT count(*) AS total,coalesce(sum(amount_paise) FILTER (WHERE status='verified'),0) AS verified_paise,coalesce(sum(amount_paise) FILTER (WHERE status='requested'),0) AS requested_paise,coalesce(sum(amount_paise) FILTER (WHERE status='cancelled'),0) AS cancelled_paise,count(*) FILTER (WHERE status='requested') AS pending FROM veloryz_studio.studio_payments$contract$,'UTF8')),'hex'),$contract$SELECT count(*) AS total,coalesce(sum(amount_paise) FILTER (WHERE status='verified'),0) AS verified_paise,coalesce(sum(amount_paise) FILTER (WHERE status='requested'),0) AS requested_paise,coalesce(sum(amount_paise) FILTER (WHERE status='cancelled'),0) AS cancelled_paise,count(*) FILTER (WHERE status='requested') AS pending FROM veloryz_studio.studio_payments$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT id,reference,title,amount_paise,status,created_at,version,token,receipt_reference,reconciliation_note,verified_at,count(*) OVER () AS matches FROM veloryz_studio.studio_payments WHERE (?='all' OR status=?) AND position(lower(?) in lower(reference || ' ' || title || ' ' || coalesce(receipt_reference,'')))>0 ORDER BY created_at DESC,id DESC LIMIT 50 OFFSET ?$contract$,'UTF8')),'hex'),$contract$SELECT id,reference,title,amount_paise,status,created_at,version,token,receipt_reference,reconciliation_note,verified_at,count(*) OVER () AS matches FROM veloryz_studio.studio_payments WHERE (?='all' OR status=?) AND position(lower(?) in lower(reference || ' ' || title || ' ' || coalesce(receipt_reference,'')))>0 ORDER BY created_at DESC,id DESC LIMIT 50 OFFSET ?$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT previous_status,status,receipt_reference,reconciliation_note,recorded_at,version FROM veloryz_studio.studio_payment_events WHERE payment_id=? ORDER BY version DESC LIMIT 100$contract$,'UTF8')),'hex'),$contract$SELECT previous_status,status,receipt_reference,reconciliation_note,recorded_at,version FROM veloryz_studio.studio_payment_events WHERE payment_id=? ORDER BY version DESC LIMIT 100$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$UPDATE veloryz_studio.studio_payments SET status=?,receipt_reference=?,reconciliation_note=?,verified_at=?,version=version+1 WHERE id=? AND version=? RETURNING id$contract$,'UTF8')),'hex'),$contract$UPDATE veloryz_studio.studio_payments SET status=?,receipt_reference=?,reconciliation_note=?,verified_at=?,version=version+1 WHERE id=? AND version=? RETURNING id$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT b.reference,b.agreed_paise,b.version,b.updated_at,e.budget AS proposed_budget,coalesce(p.verified,0) AS verified_paise,coalesce(p.pending,0) AS pending_paise FROM veloryz_studio.studio_finance_budgets b JOIN veloryz_studio.studio_enquiries e ON e.reference=b.reference LEFT JOIN (SELECT reference,sum(amount_paise) FILTER (WHERE status='verified') AS verified,sum(amount_paise) FILTER (WHERE status='requested') AS pending FROM veloryz_studio.studio_payments GROUP BY reference) p ON p.reference=b.reference ORDER BY b.updated_at DESC,b.reference LIMIT 200$contract$,'UTF8')),'hex'),$contract$SELECT b.reference,b.agreed_paise,b.version,b.updated_at,e.budget AS proposed_budget,coalesce(p.verified,0) AS verified_paise,coalesce(p.pending,0) AS pending_paise FROM veloryz_studio.studio_finance_budgets b JOIN veloryz_studio.studio_enquiries e ON e.reference=b.reference LEFT JOIN (SELECT reference,sum(amount_paise) FILTER (WHERE status='verified') AS verified,sum(amount_paise) FILTER (WHERE status='requested') AS pending FROM veloryz_studio.studio_payments GROUP BY reference) p ON p.reference=b.reference ORDER BY b.updated_at DESC,b.reference LIMIT 200$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$INSERT INTO veloryz_studio.studio_finance_budgets(reference,agreed_paise,version,updated_at) SELECT ?,?,1,? WHERE EXISTS (SELECT 1 FROM veloryz_studio.studio_enquiries WHERE reference=?) AND (?=0 OR EXISTS (SELECT 1 FROM veloryz_studio.studio_finance_budgets WHERE reference=? AND version=?)) ON CONFLICT(reference) DO UPDATE SET agreed_paise=EXCLUDED.agreed_paise,version=studio_finance_budgets.version+1,updated_at=EXCLUDED.updated_at WHERE studio_finance_budgets.version=? RETURNING reference$contract$,'UTF8')),'hex'),$contract$INSERT INTO veloryz_studio.studio_finance_budgets(reference,agreed_paise,version,updated_at) SELECT ?,?,1,? WHERE EXISTS (SELECT 1 FROM veloryz_studio.studio_enquiries WHERE reference=?) AND (?=0 OR EXISTS (SELECT 1 FROM veloryz_studio.studio_finance_budgets WHERE reference=? AND version=?)) ON CONFLICT(reference) DO UPDATE SET agreed_paise=EXCLUDED.agreed_paise,version=studio_finance_budgets.version+1,updated_at=EXCLUDED.updated_at WHERE studio_finance_budgets.version=? RETURNING reference$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
